import java.util.Scanner;

public class Main {
    public static int readInt(Scanner scanner) {
        int num = 0;
        while (true) {
            if (!scanner.hasNext()) break;
            String token = scanner.next();
            if (token.matches("\\d+")) {
                num = Integer.parseInt(token);
                break;
            }
        }
        return num;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.next();
        StringBuilder t = new StringBuilder();
        t.append(s.charAt(0));
        boolean atFlag = false;
        int length = s.length();
        s += "\u0001\u0001\u0001\u0001"; // Append special characters
        int i = 1;
        while (i < length) {
            if (s.charAt(i) == 'd' && s.charAt(i + 1) == 'o' && s.charAt(i + 2) == 't' && s.charAt(i + 3) != '\u0001') {
                t.append('.');
                i += 3;
            } else if (s.charAt(i) == 'a' && s.charAt(i + 1) == 't' && !atFlag) {
                t.append('@');
                atFlag = true;
                i += 2;
            } else {
                t.append(s.charAt(i));
                i++;
            }
        }
        System.out.println(t.toString());
        scanner.close();
    }
}
